import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const java=readFileSync(new URL('../native/android/DAGApkUpdater.java',import.meta.url),'utf8');
const plugin=readFileSync(new URL('../native/android/DAGCarModePlugin.java',import.meta.url),'utf8');
const config=readFileSync(new URL('../scripts/configure-android-media.mjs',import.meta.url),'utf8');
const build=readFileSync(new URL('./workflows/build-android.yml',import.meta.url),'utf8');
const bridge=readFileSync(new URL('../native/native-bridge.js',import.meta.url),'utf8');
const script=readFileSync(new URL('../script.js',import.meta.url),'utf8');
assert.match(java,/new DAGServerDns\(\)/);
assert.match(java,/MessageDigest\.isEqual/);
assert.match(java,/SHA-256/);
assert.match(java,/verify\(part, remote\)/);
assert.match(java,/getPackageArchiveInfo/);
assert.match(java,/ACTION_MANAGE_UNKNOWN_APP_SOURCES/);
assert.match(java,/FLAG_GRANT_READ_URI_PERMISSION/);
assert.match(java,/FileProvider\.getUriForFile/);
assert.match(java,/followRedirects\(false\)/);
assert.match(java,/followSslRedirects\(false\)/);
assert.doesNotMatch(java,/setHostnameVerifier|trustAll/);
assert.match(java,/android\.package-archive/);
assert.match(plugin,/checkApkUpdate\(PluginCall call\)/);
assert.match(plugin,/installApkUpdate\(PluginCall call\)/);
assert.match(config,/REQUEST_INSTALL_PACKAGES/);
assert.match(config,/dagstudio_update_paths/);
assert.match(config,/android\.support\.FILE_PROVIDER_PATHS/);
assert.match(build,/cp native\/android\/DAGApkUpdater\.java/);
assert.match(build,/Deploy APK mirror for DNS-restricted CC3 devices/);
assert.match(build,/NATIVE_APK_MIRROR_TLS_SHA256_OK/);
assert.match(bridge,/apkInstaller: \{/);
assert.match(script,/const WEB_BUILD_LABEL = '2319'/);
const manual=script.slice(script.indexOf('window.manualUpdateApplication ='),
                          script.indexOf('let serviceWorkerRegistrationPromise'));
assert.match(manual,/checkNativeLiveUpdate\(true, true\)/);
assert.doesNotMatch(manual,/installer\.check\(|installer\.install\(|apkInstaller/);
assert.match(java,/MANIFEST_TTL_MS/);
assert.match(java,/builder\.header\("Range", "bytes="/);
assert.match(java,/Content-Range/);
assert.match(java,/verifiedSha\(part, expectedHash\)/);
assert.match(java,/progress\("downloading"/);
assert.match(java,/progress\("retrying"/);
assert.match(java,/callTimeout\(210, TimeUnit\.SECONDS\)/);
assert.match(plugin,/notifyListeners\("apkUpdateProgress"/);
assert.match(bridge,/dag-apk-update-progress/);
assert.doesNotMatch(build, /      - "style\.css"/);
assert.match(script,/if \(!manual\) return \{ status: 'manual-only' \}/);
console.log('IN_APP_APK_UPDATE_CERT_SHA256_VERSION_PACKAGE_DNS_MIRROR_OK');
